function renderSvgNode(node, idx) {
  if (typeof node === 'string') return node;
  const [tag, props, children] = node;
  const nextProps = {...props, key: idx};
  if (!children || children.length === 0) {
    return createElement(tag, nextProps);
  }
  return createElement(tag, nextProps, children.map((ch, cIdx) => renderSvgNode(ch, cIdx)));
}

function makeTiBIconComponent(slug, spec) {
  function TiBThreeToneSvg(props) {
    const {style, ...rest} = props || {};
    return createElement(
      'svg',
      {
        xmlns: 'http://www.w3.org/2000/svg',
        viewBox: '0 0 24 24',
        fill: 'none',
        stroke: 'currentColor',
        strokeWidth: '1.7',
        strokeLinecap: 'round',
        strokeLinejoin: 'round',
        'data-color-system': 'tib-three-tone-v1',
        style: {color: 'var(--tib-primary, #123B70)', ...style},
        ...rest,
      },
      spec.nodes.map((node, idx) => renderSvgNode(node, idx))
    );
  }
  TiBThreeToneSvg.displayName = `TiBIcon_${slug}`;
  return TiBThreeToneSvg;
}

export const TIB_THREE_TONE_COMPONENTS = Object.freeze(
  Object.fromEntries(
    Object.entries(TIB_ICON_SPECS).map(([slug, spec]) => [
      slug,
      Object.freeze({
        key: `tib.${slug}`,
        slug,
        label: `TiB · ${spec.label}`,
        component: makeTiBIconComponent(slug, spec),
      }),
    ])
  )
);

export function normalizeTiBIconKey(rawKey) {
  const s = String(rawKey || '').trim().toLowerCase().replace(/\.svg$/, '');
  if (s.startsWith('tib.')) {
    return `tib.${s.slice(4).replace(/-/g, '_')}`;
  }
  const slug = s.replace(/-/g, '_');
  if (TIB_THREE_TONE_COMPONENTS[slug]) {
    return `tib.${slug}`;
  }
  return rawKey;
}
